document.addEventListener('DOMContentLoaded',()=>{const b=document.querySelector('[data-audiovisual-preview]');if(!b)return;const a=JSON.parse(b.dataset.items),area=b.querySelector('[data-media]'),title=b.querySelector('h3'),count=b.querySelector('[data-count]'),pause=b.querySelector('[data-pause]');let i=0,stopped=false;function show(n){i=(n+a.length)%a.length;area.replaceChildren();let v=document.createElement('div');v.className='audiovisual-placeholder';let thumb=document.createElement('iframe');thumb.src=a[i].src;thumb.title=a[i].title;thumb.tabIndex=-1;thumb.setAttribute('aria-hidden','true');thumb.style.pointerEvents='none';v.append(thumb);let open=document.createElement('button');open.textContent='Assistir vídeo';open.onclick=()=>{stopped=true;pause.textContent='Continuar';pause.setAttribute('aria-pressed','true');const f=document.createElement('iframe');f.src=a[i].src;f.title=a[i].title;f.allow='autoplay; fullscreen';f.allowFullscreen=true;area.replaceChildren(f)};v.append(open);area.append(v);title.textContent=a[i].title;count.textContent=(i+1)+' de '+a.length}b.querySelector('[data-prev]').onclick=()=>show(i-1);b.querySelector('[data-next]').onclick=()=>show(i+1);pause.onclick=()=>{stopped=!stopped;pause.textContent=stopped?'Continuar':'Pausar';pause.setAttribute('aria-pressed',String(stopped))};show(0);setInterval(()=>{if(!stopped)show(i+1)},8000)});